{
  "apiVersion": 1,
  "type": "hook.detail",
  "package": "@astryxdesign/core",
  "data": {
    "name": "usePowerSearchConfig",
    "displayName": "usePowerSearchConfig",
    "group": "PowerSearch",
    "keywords": [
      "powersearch",
      "search",
      "filter",
      "filters",
      "query builder",
      "table filter",
      "usePowerSearchConfig",
      "createPowerSearchConfig"
    ],
    "params": [
      {
        "name": "definitions",
        "type": "ReadonlyArray<FieldDefinition>",
        "description": "Typed field definitions (key, type, label, enumValues) used to build PowerSearch fields and operators.",
        "required": true
      },
      {
        "name": "configName",
        "type": "string",
        "description": "Optional name for the PowerSearchConfig object (defaults to \"PowerSearchConfig\").",
        "required": false
      }
    ],
    "returns": [
      {
        "name": "config",
        "type": "PowerSearchConfig",
        "description": "Memoized PowerSearch configuration object with fields and type-appropriate operators."
      },
      {
        "name": "applyFilters",
        "type": "<T extends InferData<D>>(filters: ReadonlyArray<PowerSearchFilter>, data: ReadonlyArray<T>) => T[]",
        "description": "Client-side filtering helper that filters a dataset using the active PowerSearch filter rules."
      }
    ],
    "usage": {
      "description": "Memoizes a PowerSearch configuration built from typed field definitions and returns it along with an applyFilters function for client-side filtering. Automatically maps field types (string, number, boolean, date, enum, etc.) to their canonical operators and provides an efficient predicate evaluator to filter datasets.",
      "bestPractices": [
        {
          "guidance": true,
          "description": "Declare field definitions as const outside the component or memoize them so usePowerSearchConfig only recalculates when needed."
        },
        {
          "guidance": true,
          "description": "Pass the returned config to PowerSearch and use applyFilters to compute the filtered data rows for a Table or List."
        },
        {
          "guidance": false,
          "description": "Recreate field definitions inline on every render without as const or memoization."
        }
      ]
    },
    "relatedComponents": [
      "PowerSearch",
      "Table"
    ],
    "relatedHooks": [
      "useTableFilterState",
      "useTableFiltering"
    ],
    "importPath": "@astryxdesign/core/PowerSearch",
    "category": "utilities"
  },
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
